package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/stops") @RequiredArgsConstructor public class StopController{private final CatalogService s;@GetMapping public List<CatalogResponses.Stop> all(){return s.stops();}@GetMapping("/{id}") public CatalogResponses.Stop one(@PathVariable Long id){return s.stop(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Stop create(@Valid @RequestBody CatalogRequests.Stop r){return s.saveStop(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Stop update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Stop r){return s.saveStop(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteStop(id);}}
